const r = $input.first().json.report || {};
const totals = r.totals || {};
const byTrade = Array.isArray(r.by_trade) ? r.by_trade : [];
const topSup = Array.isArray(r.top_suppliers) ? r.top_suppliers : [];
const stale = Array.isArray(r.stale_pending) ? r.stale_pending : [];

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function money(n) { return n != null && n > 0 ? Number(n).toLocaleString('es-ES') + ' EUR' : '-'; }
function dateShort(s) { if (!s) return '-'; return new Date(s).toISOString().substring(0,10); }
function pct(num, den) { return den > 0 ? Math.round((num/den)*100) + '%' : '-'; }

const rowsTrade = byTrade.map(t => {
  const responseRate = t.quotes_total > 0 ? Math.round((t.quoted + t.accepted) / t.quotes_total * 100) : 0;
  const acceptRate = t.quotes_total > 0 ? Math.round(t.accepted / t.quotes_total * 100) : 0;
  return `<tr>
    <td>${esc(t.trade_type)}</td>
    <td style="text-align:right">${t.quotes_total}</td>
    <td style="text-align:right">${responseRate}%</td>
    <td style="text-align:right">${acceptRate}%</td>
    <td style="text-align:right${t.stale > 0 ? ';color:#c00;font-weight:600' : ''}">${t.stale}</td>
    <td style="text-align:right">${money(t.avg_amount)}</td>
    <td style="text-align:right">${t.unique_suppliers}</td>
    <td>${dateShort(t.last_quote_at)}</td>
  </tr>`;
}).join('');

const rowsSup = topSup.map(s => `<tr>
  <td>${esc(s.supplier_name)} <small style="color:#888">${esc(s.supplier_email)}</small></td>
  <td style="text-align:right">${s.quotes_total}</td>
  <td style="text-align:right">${s.quoted}</td>
  <td style="text-align:right;font-weight:600">${s.accepted}</td>
  <td style="text-align:right">${money(s.avg_amount)}</td>
  <td>${dateShort(s.last_contact_at)}</td>
</tr>`).join('');

const rowsStale = stale.length ? stale.map(s => `<tr style="background:${s.days_waiting > 30 ? '#fee' : '#fff8e0'}">
  <td>${esc(s.supplier_name)} <small style="color:#888">${esc(s.supplier_email)}</small></td>
  <td>${esc(s.trade_type || '-')}</td>
  <td>${dateShort(s.sent_at)}</td>
  <td style="text-align:right;font-weight:600">${s.days_waiting}d</td>
</tr>`).join('') : '<tr><td colspan="4" style="text-align:center;color:#888;padding:18px">Sin solicitudes pendientes >14d (estado saludable)</td></tr>';

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Trades Summary - ArquitAI</title>
<style>
  body{font-family:system-ui,sans-serif;max-width:1200px;margin:32px auto;padding:0 20px;color:#222;background:#f7f7f8}
  h1{margin:0 0 8px}
  .sub{color:#888;font-size:13px;margin-bottom:24px}
  h2{margin:32px 0 12px;font-size:18px;border-bottom:1px solid #ddd;padding-bottom:6px}
  .cards{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin-bottom:24px}
  .card{background:#fff;border:1px solid #ddd;border-radius:8px;padding:14px}
  .card h3{margin:0 0 4px;font-size:11px;color:#666;text-transform:uppercase;letter-spacing:.5px}
  .card .v{font-size:22px;font-weight:600}
  table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #ddd;border-radius:8px;overflow:hidden}
  th,td{padding:8px 12px;border-bottom:1px solid #eee;font-size:13px;text-align:left;vertical-align:middle}
  th{background:#f0f0f3;font-weight:600;font-size:11px;text-transform:uppercase;color:#555}
  tr:last-child td{border-bottom:none}
  .meta{font-size:12px;color:#888;margin-top:24px}
  @media (max-width:900px){.cards{grid-template-columns:repeat(3,1fr)}}
</style></head><body>
<h1>Trades Summary - ArquitAI</h1>
<p class="sub">Cotizaciones a gremios + ratios + suppliers historicos. Fuente: tabla trade_quotes.</p>
<div class="cards">
  <div class="card"><h3>Total quotes</h3><div class="v">${totals.quotes_total || 0}</div></div>
  <div class="card"><h3>30 dias</h3><div class="v">${totals.quotes_30d || 0}</div></div>
  <div class="card"><h3>Pending</h3><div class="v">${totals.pending || 0}</div></div>
  <div class="card"><h3>Quoted</h3><div class="v">${totals.quoted || 0}</div></div>
  <div class="card"><h3>Aceptados</h3><div class="v">${totals.accepted || 0}</div></div>
  <div class="card"><h3>Rechazados</h3><div class="v">${totals.rejected || 0}</div></div>
</div>
<h2>Por gremio</h2>
<table>
  <thead><tr><th>trade_type</th><th style="text-align:right">quotes</th><th style="text-align:right">response</th><th style="text-align:right">accept</th><th style="text-align:right">stale</th><th style="text-align:right">avg amount</th><th style="text-align:right">suppliers</th><th>last quote</th></tr></thead>
  <tbody>${rowsTrade || '<tr><td colspan="8" style="text-align:center;color:#888;padding:18px">Sin trade_quotes registrados</td></tr>'}</tbody>
</table>
<h2>Top suppliers (15 con mas quotes)</h2>
<table>
  <thead><tr><th>supplier</th><th style="text-align:right">quotes</th><th style="text-align:right">quoted</th><th style="text-align:right">accepted</th><th style="text-align:right">avg amount</th><th>last contact</th></tr></thead>
  <tbody>${rowsSup || '<tr><td colspan="6" style="text-align:center;color:#888;padding:18px">Sin suppliers</td></tr>'}</tbody>
</table>
<h2>Solicitudes sin respuesta (>14d)</h2>
<table>
  <thead><tr><th>supplier</th><th>trade_type</th><th>enviada</th><th style="text-align:right">dias</th></tr></thead>
  <tbody>${rowsStale}</tbody>
</table>
<div class="meta">Generado ${new Date().toISOString()}</div>
</body></html>`;

return [{ json: { html } }];
